class Solution:
    '''动态规划+最低设置位
    '''
    def countBits(self, num: int) -> List[int]:
        ans = [0]*(num+1)
        for i in range(num+1):
            ans[i]=ans[i>>1]+(i&1) # i&1 即 i mod 2
        return ans

