class Solution:
    '''动态规划+最高有效位
    '''
    def countBits(self, num: int) -> List[int]:
        ans = [0]*(num+1)
        # generate ans for [0,b)
        i = 0
        b = 1
        ans[0] = 0
        while b <= num:
            # generate [b,2b) or [b,num] for [0,b] 
            while i<b and i+b<=num:
                ans[i+b]= ans[i]+1
                i+=1
            i=0 # reset i
            b <<= 1
        return ans

